#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<string> g(n);
    for (int i = 0; i < n; ++i) cin >> g[i];

    const int dx[4] = {-1, 1, 0, 0};
    const int dy[4] = {0, 0, -1, 1};
    vector<vector<int>> gain(n, vector<int>(m, 0));
    int base = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int bad = 0, bi = -1, bj = -1;
            for (int k = 0; k < 4; ++k) {
                int ni = i + dx[k], nj = j + dy[k];
                if (ni >= 0 && ni < n && nj >= 0 && nj < m && g[ni][nj] == '#') {
                    ++bad;
                    bi = ni;
                    bj = nj;
                }
            }
            if (g[i][j] == '.') {
                if (bad == 0) {
                    ++base;
                } else if (bad == 1) {
                    ++gain[bi][bj];
                }
            } else {
                if (bad == 0) {
                    ++gain[i][j];
                }
            }
        }
    }

    int bestGain = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            bestGain = max(bestGain, gain[i][j]);

    cout << base + bestGain << '\n';
    return 0;
}
